    "html[data-huahua-dsh-record-replay-active]:not([data-dsh-taskboard-active]):not([data-dsh-ssh-active]) [data-pane='conversation'] > :not([data-huahua-dsh-record-replay-view]),",
    "html[data-huahua-dsh-record-replay-active]:not([data-dsh-taskboard-active]):not([data-dsh-ssh-active]) [class*='centerCol'] > :not([data-huahua-dsh-record-replay-view]) { display: none !important; }",
